<?php $token=htmlspecialchars($_GET['token']??'',ENT_QUOTES,'UTF-8'); ?>
<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Responder orçamento · Manutenções Marques</title><style>body{font-family:Inter,system-ui;background:#f6f7fb;color:#172033;margin:0}.card{max-width:620px;margin:60px auto;background:#fff;border:1px solid #e3e7ef;border-radius:20px;padding:28px}.actions{display:flex;gap:12px;margin-top:22px}button{border:0;border-radius:12px;padding:13px 18px;font:inherit;cursor:pointer}.ok{background:#166534;color:#fff}.no{background:#b91c1c;color:#fff}.muted{color:#64748b}</style></head><body><main class="card"><small class="muted">MANUTENÇÕES MARQUES</small><h1>Responder orçamento</h1><p>Confira o orçamento recebido e escolha aprovar ou recusar. A resposta será registrada diretamente no protocolo do serviço.</p><div class="actions"><button class="ok" data-status="APROVADO">Aprovar orçamento</button><button class="no" data-status="RECUSADO">Recusar</button></div><p id="msg"></p></main><script>const token=<?=json_encode($token)?>;document.querySelectorAll('button').forEach(b=>b.onclick=async()=>{try{const r=await fetch('../api/orcamentos/responder_publico.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({token,status:b.dataset.status})});const j=await r.json();document.getElementById('msg').textContent=j.status?'Resposta registrada: '+j.dados.status:j.mensagem;document.querySelectorAll('button').forEach(x=>x.disabled=true)}catch(e){document.getElementById('msg').textContent='Não foi possível registrar a resposta.'}});</script></body></html>
